NEW_FILES = {'src/language/reflexion.py': '"""parche-109: REFLEXION. El LCM repasa todos los conceptos que tiene en memoria y descubre los NEXOS que hay entre ellos, sin que nadie se los haya dicho:\n  - SE_PARECE_A    conceptos cercanos (mismos antepasados, mismas partes, palabras comunes en su definicion). Motivo: "los dos son tipos de «felino»".\n  - RELACIONADO_CON  A aparece en la definicion de B (y no es su tipo): "«bicicleta» se define con «pedal»".\n  - PARTE_DE / MIEMBRO_DE / HECHO_DE  lo que el diccionario sabe y la memoria aun no tenia.\n  - CONTRARIO_DE   antonimos entre conceptos de la memoria.\nTodo sale del diccionario de conceptos y de lo que hay en memoria; cada nexo lleva su motivo ("por") y un peso. El resultado se guarda como cartucho `reflexion`\n(se puede retirar sin dejar rastro) y se recalcula cuando cambia la memoria. No hay aleatoriedad: misma memoria, mismos nexos."""\nimport re\nimport time\nfrom collections import defaultdict\n\nCARTUCHO = "reflexion"\nGENERICOS = {"hombre", "mujer", "persona", "gente", "cosa", "lugar", "parte", "forma", "tipo", "clase", "grupo", "humano", "hembra", "macho", "cuerpo", "área", "superficie", "sustancia", "material", "aire", "agua"}   # aparecen en miles de definiciones: enlazarlos seria ruido\nSURFACE = {"SE_PARECE_A": "{s} se parece a {o}", "RELACIONADO_CON": "{s} está relacionado con {o}", "CONTRARIO_DE": "{s} es lo contrario de {o}", "MIEMBRO_DE": "{s} es miembro de {o}", "HECHO_DE": "{s} está hecho de {o}"}\n\n\ndef _C():\n    from src.language import conceptos\n    return conceptos\n\n\ndef _D():\n    from src.language import definiciones\n    return definiciones\n\n\ndef _nom(mem, k):\n    v = (getattr(mem, "display", {}) or {}).get(k) or str(k).replace("_", " ").lower()\n    return re.sub(r"^(?:el|la|los|las|un|una)\\s+", "", v.strip(), flags=re.I)\n\n\ndef _resolver(mem, claves):\n    """{clave: concepto} para las CLASES de la memoria que tienen sentido claro en el diccionario (coherente con lo que la memoria dice de ellas)."""\n    C = _C()\n    ids, dudosos = {}, []\n    padres = defaultdict(set)\n    for f in mem.facts:\n        if str(f["p"]).upper() == "ES" and not f.get("neg"):\n            padres[f["s"]].add(f["o"])\n    for k in sorted(claves):\n        nombre = _nom(mem, k)\n        if not nombre or not nombre[:1].islower() or len(nombre) < 3:                 # Ana, Madrid, Rex: no son clases del diccionario\n            continue\n        cs = C.conceptos(nombre)\n        if not cs:\n            continue\n        c = cs[0]\n        ok = True\n        if padres.get(k):\n            asc = set(C.ascendentes(c, 12))\n            nombres_asc = {C.nrm(C.etiqueta(x) or "") for x in asc} - {""}\n            ok = False\n            for p in padres[k]:\n                pc = C.conceptos(_nom(mem, p))\n                if C.nrm(_nom(mem, p)) in nombres_asc or (pc and (pc[0] in asc or any(x in asc for x in pc[:2]))):\n                    ok = True\n                    break\n        if ok:\n            ids[k] = c\n        else:\n            dudosos.append(k)\n    return ids, dudosos\n\n\ndef _vecinos(ids, k, minimo):\n    """k vecinos mas parecidos de cada concepto (coseno de rasgos) con indice invertido; ignora rasgos que tienen casi todos (antepasados muy generales)."""\n    C = _C()\n    claves = sorted(ids)\n    vec = {kk: C.vector(ids[kk]) for kk in claves}\n    nor = {kk: sum(x * x for x in v.values()) ** 0.5 for kk, v in vec.items()}\n    post = defaultdict(list)\n    for kk, v in vec.items():\n        for f in v:\n            post[f].append(kk)\n    tope = max(60, len(claves) // 12)\n    out = {}\n    for kk in claves:\n        acc = defaultdict(float)\n        for f, w in vec[kk].items():\n            lst = post[f]\n            if len(lst) > tope:\n                continue\n            for o in lst:\n                if o != kk:\n                    acc[o] += w * vec[o][f]\n        rank = sorted(((s / (nor[kk] * nor[o]) if nor[kk] * nor[o] else 0.0, o) for o, s in acc.items()), key=lambda x: (-x[0], x[1]))\n        out[kk] = [(round(s, 3), o) for s, o in rank[:k] if s >= minimo]\n    return out\n\n\ndef reflexionar(mem, k=3, minimo=0.45, log=None):\n    """-> {"hechos": [...], "informe": {...}}. `mem` NO debe llevar montado el cartucho de reflexion (lo hace Motor.reflexionar)."""\n    t0 = time.time()\n    C, D = _C(), _D()\n    if not C.disponible():\n        return {"hechos": [], "informe": {"error": "El diccionario de conceptos no está instalado."}}\n    claves = {f[x] for f in mem.facts if not f.get("neg") and f.get("cart") != CARTUCHO for x in ("s", "o")}\n    ids, dudosos = _resolver(mem, claves)\n    inv = {}\n    for kk, c in ids.items():\n        inv.setdefault(c, kk)\n    X = D._load() if D.disponible() else {"ok": False}\n    d = C._load()\n    existentes = {(f["s"], f["p"], f["o"]) for f in mem.facts if f.get("cart") != CARTUCHO}\n    ligados = set()\n    for f in mem.facts:\n        if f.get("cart") != CARTUCHO and str(f["p"]).upper() in ("ES", "PARTE_DE"):\n            ligados.add(frozenset((f["s"], f["o"])))\n    hechos, vistos = [], set()\n\n    def nuevo(s, p, o, por, peso, simetrico=False):\n        if s == o or (s, p, o) in existentes:\n            return\n        clave = (min(s, o), p, max(s, o)) if simetrico else (s, p, o)\n        if clave in vistos:\n            return\n        if frozenset((s, o)) in ligados and p in ("SE_PARECE_A", "RELACIONADO_CON"):\n            return\n        vistos.add(clave)\n        hechos.append({"s": s, "p": p, "o": o, "n": 1, "t": 0, "source": "reflexion", "imp": 1.0, "tick": 0, "archived": False, "neg": False, "when": "", "when_disp": "", "when_abs": None, "q": "",\n                       "por": por, "peso": round(float(peso), 3)})\n\n    # 1. parecidos\n    for kk, lst in _vecinos(ids, k, minimo).items():\n        for s, o in lst:\n            a, b = ids[kk], ids[o]\n            cm = D.comun_es(a, b) if X["ok"] else None\n            lab = C.etiqueta(cm) if cm is not None else None\n            if (cm is None and X["ok"]) or cm in (a, b):\n                continue                                                        # sin un tipo común concreto el parecido es ruido (perro ~ hombre)\n            por = f"los dos son tipos de «{lab}»" if lab and lab not in (_nom(mem, kk), _nom(mem, o)) else "comparten antepasados, partes y palabras de su definición"\n            nuevo(kk, "SE_PARECE_A", o, por, s, simetrico=True)\n    # 2. definicion, partes, miembros, sustancias, contrarios\n    entrada = defaultdict(int)\n    for kk, c in sorted(ids.items()):\n        if X["ok"]:\n            arriba = set(C.ascendentes(c))\n            n_rel = 0\n            for t in X["gl"].get(c, []):\n                o = inv.get(t)\n                if o and t not in arriba and t != c and not D._alto(t) and n_rel < 3 and entrada[o] < 15 and _nom(mem, o) not in GENERICOS:\n                    antes_ = len(hechos)\n                    nuevo(kk, "RELACIONADO_CON", o, f"«{_nom(mem, kk)}» se define con «{_nom(mem, o)}»", 0.5)\n                    if len(hechos) > antes_:\n                        n_rel += 1\n                        entrada[o] += 1\n        for t in d["parte"].get(c, []):\n            o = inv.get(t)\n            if o:\n                nuevo(o, "PARTE_DE", kk, f"el diccionario dice que «{_nom(mem, o)}» es parte de «{_nom(mem, kk)}»", 0.8)\n        for t in d["miembro"].get(c, []):\n            o = inv.get(t)\n            if o:\n                nuevo(o, "MIEMBRO_DE", kk, f"el diccionario dice que «{_nom(mem, o)}» es miembro de «{_nom(mem, kk)}»", 0.8)\n        for t in d["sustancia"].get(c, []):\n            o = inv.get(t)\n            if o:\n                nuevo(kk, "HECHO_DE", o, f"el diccionario dice que «{_nom(mem, kk)}» está hecho de «{_nom(mem, o)}»", 0.8)\n        for t in d["ant"].get(c, []):\n            o = inv.get(t)\n            if o:\n                nuevo(kk, "CONTRARIO_DE", o, "son antónimos en el diccionario", 0.9, simetrico=True)\n    dudas = []\n    padres = defaultdict(list)\n    for f in mem.facts:\n        if str(f["p"]).upper() == "ES" and not f.get("neg") and f.get("cart") != CARTUCHO:\n            padres[f["s"]].append(f["o"])\n    for kk in dudosos:\n        cs = C.conceptos(_nom(mem, kk))\n        if cs and padres.get(kk):\n            dudas.append({"concepto": _nom(mem, kk), "memoria": "es " + " y ".join(_nom(mem, p) for p in padres[kk][:2]), "diccionario": "es " + (" > ".join(C.cadena(cs[0], 3)) or "?")})\n    hechos.sort(key=lambda h: (h["p"], h["s"], h["o"]))\n    por_tipo = defaultdict(list)\n    for h in hechos:\n        por_tipo[h["p"]].append(h)\n    grado = defaultdict(int)\n    for h in hechos:\n        grado[h["s"]] += 1\n        grado[h["o"]] += 1\n    con = set(grado)\n    informe = {"conceptos": len(ids), "sin_sentido_claro": len(dudosos), "nexos": len(hechos), "segundos": round(time.time() - t0, 2), "por_tipo": {p: len(v) for p, v in sorted(por_tipo.items())},\n               "ejemplos": {p: [{"s": _nom(mem, h["s"]), "o": _nom(mem, h["o"]), "por": h["por"]} for h in sorted(v, key=lambda x: -x["peso"])[:6]] for p, v in sorted(por_tipo.items())},\n               "centrales": [{"concepto": _nom(mem, kk), "nexos": g} for kk, g in sorted(grado.items(), key=lambda x: (-x[1], x[0]))[:10]],\n               "aislados": len([kk for kk in ids if kk not in con]), "dudas": dudas[:30], "fecha": time.strftime("%Y-%m-%d %H:%M")}\n    if log:\n        log(f"[reflexion] {len(ids)} conceptos -> {len(hechos)} nexos en {informe[\'segundos\']} s")\n    return {"hechos": hechos, "informe": informe}\n\n\ndef guardar(res, mem, base="cartuchos"):\n    """Escribe cartuchos/reflexion.json y lo inserta. Devuelve la ruta."""\n    from src.memory import cartuchos\n    disp = {}\n    for h in res["hechos"]:\n        for x in (h["s"], h["o"]):\n            disp.setdefault(x, _nom(mem, x))\n    cont = {"hechos": res["hechos"], "alias": {}, "verb_isa": {}, "defs": {}, "surface": dict(SURFACE), "display": disp, "opposites": [[_nom(mem, h["s"]), _nom(mem, h["o"])] for h in res["hechos"] if h["p"] == "CONTRARIO_DE"]}\n    ruta = cartuchos.guardar_cartucho(CARTUCHO, cont, {"fuente": "reflexión sobre los conceptos de la memoria", "descripcion": "Nexos descubiertos entre conceptos (parecidos, definiciones, partes, contrarios)", "informe": res["informe"]}, base)\n    cartuchos.insertar(CARTUCHO, base)\n    return ruta\n', 'tests/test_parche109.py': '"""parche-109: reflexion (nexos entre conceptos), \'palabras similares a X\', sentidos de circulo/esfera/linea, saltamontes invariable, cubiertos."""\nimport json\nimport os\nimport tempfile\nimport threading\nimport urllib.request\n\nimport pytest\n\nfrom src.language import conceptos as C\nfrom src.language import reflexion as R\nfrom src.memory import cartuchos\nfrom src.memory.store import MemoryStore\n\n\nclass _P:\n    def parse(self, *a, **k):\n        return []\n\n\ndef _mem(pares):\n    d = tempfile.mkdtemp()\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    for s, p, o in pares:\n        mem.add_fact((s, p, o), source="mundo")\n        mem.display.setdefault(s.upper(), s)\n        mem.display.setdefault(o.upper(), o)\n    return mem, d\n\n\nBASE = [("perro", "ES", "cánido"), ("lobo", "ES", "cánido"), ("zorro", "ES", "cánido"), ("gato", "ES", "felino"), ("león", "ES", "felino"), ("tigre", "ES", "felino"),\n        ("martes", "ES", "día"), ("jueves", "ES", "día"), ("lunes", "ES", "día")]\n\n\ndef test_reflexion_encuentra_parecidos_con_motivo():\n    mem, _ = _mem(BASE)\n    r = R.reflexionar(mem)\n    sp = [(h["s"], h["o"], h["por"]) for h in r["hechos"] if h["p"] == "SE_PARECE_A"]\n    assert sp, r["informe"]\n    assert any({a, b} <= {"PERRO", "LOBO", "ZORRO"} for a, b, _ in sp) and any({a, b} <= {"GATO", "LEÓN", "TIGRE"} for a, b, _ in sp)\n    assert all(por for _, _, por in sp)\n    assert not any({a, b} & {"PERRO", "GATO"} == {a, b} for a, b, _ in sp)         # perro y gato no son del mismo tipo concreto en esta memoria\n\n\ndef test_reflexion_es_determinista_y_no_repite():\n    mem, _ = _mem(BASE)\n    a, b = R.reflexionar(mem)["hechos"], R.reflexionar(mem)["hechos"]\n    assert [(h["s"], h["p"], h["o"]) for h in a] == [(h["s"], h["p"], h["o"]) for h in b]\n    assert len({(h["s"], h["p"], h["o"]) for h in a}) == len(a)\n\n\ndef test_cartucho_reflexion_monta_y_se_retira():\n    mem, d = _mem(BASE)\n    base = os.path.join(d, "c")\n    r = R.reflexionar(mem)\n    R.guardar(r, mem, base)\n    assert "reflexion" in cartuchos.activos(base)\n    mem2 = MemoryStore(os.path.join(d, "m2.json"))\n    cartuchos.montar(mem2, base)\n    assert any(f.get("cart") == "reflexion" and f.get("por") for f in mem2.facts)\n    assert mem2.surface["SE_PARECE_A"] == "{s} se parece a {o}"\n    cartuchos.retirar("reflexion", base)\n    cartuchos.montar(mem2, base)\n    assert not mem2.facts\n\n\ndef test_reflexion_ignora_su_propio_cartucho():\n    mem, d = _mem(BASE)\n    base = os.path.join(d, "c")\n    r1 = R.reflexionar(mem)\n    R.guardar(r1, mem, base)\n    cartuchos.montar(mem, base)\n    r2 = R.reflexionar(mem)\n    assert [(h["s"], h["p"], h["o"]) for h in r1["hechos"]] == [(h["s"], h["p"], h["o"]) for h in r2["hechos"]]\n\n\ndef test_palabras_similares():\n    mem, _ = _mem([])\n    r = C.antes("Dime palabras similares a coche", mem)\n    assert r and "Sinónimos" in r and "auto" in r.lower()\n    assert C.antes("¿Qué se parece a un coche?", mem)\n\n\ndef test_sentidos_geometricos_y_cubiertos():\n    for pal, exp in (("círculo", ("figura", "forma", "óvalo")), ("esfera", ("figura", "forma", "sólido")), ("línea", ("longitud", "extensión", "forma", "figura"))):\n        c = C.conceptos(pal)[0]\n        assert any(x in " ".join(C.cadena(c, 5)).lower() for x in exp), (pal, C.cadena(c, 5))\n    assert "cubiertos" in C.describir("tenedor", None)\n\n\ndef test_saltamontes_no_es_plural():\n    from src.language.dialogue import Conversation\n    from src.language.qa import QA\n    mem, _ = _mem([("saltamontes", "ES", "insecto")])\n    conv = Conversation(mem, _P(), lambda m, p: QA(m, p.parse, lambda f: {}))\n    r = conv.say("¿Qué es un saltamontes?")\n    assert r.startswith("El saltamontes es un insecto"), r\n\n\n@pytest.fixture()\ndef srv():\n    from src.web.motor import Motor\n    from src.web.servidor import crear_servidor\n    mem, d = _mem(BASE)\n    base = os.path.join(d, "c")\n    os.makedirs(base)\n    m = Motor(mem, _P(), base)\n    s = crear_servidor(m, 0)\n    threading.Thread(target=s.serve_forever, daemon=True).start()\n    yield f"http://127.0.0.1:{s.server_address[1]}"\n    s.shutdown()\n    s.server_close()\n\n\ndef test_api_reflexion(srv):\n    g = json.loads(urllib.request.urlopen(srv + "/api/reflexion").read())\n    assert g["informe"] is None\n    rq = urllib.request.Request(srv + "/api/reflexion", b"{}", {"Content-Type": "application/json", "X-LCM-Web": "1"})\n    r = json.loads(urllib.request.urlopen(rq).read())\n    assert r["ok"] and r["informe"]["nexos"] > 0\n    g = json.loads(urllib.request.urlopen(srv + "/api/reflexion").read())\n    assert g["activo"] and g["informe"]["nexos"] == r["informe"]["nexos"]\n    k = json.loads(urllib.request.urlopen(srv + "/api/concepto?k=PERRO").read())\n    assert any(f["origen"] == "reflexion" and f["por"] for v in list(k["sale"].values()) + list(k["entra"].values()) for f in v)\n'}
SOFT = []
BLOB = ''

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    CART = json.loads(zlib.decompress(base64.b64decode(BLOB)).decode("utf-8"))
    for nom, cont in CART.items():
        pc = root / "cartuchos" / nom
        txt = json.dumps(cont, ensure_ascii=False, separators=(",", ":"))
        if not pc.exists() or pc.read_text(encoding="utf-8") != txt:
            pc.parent.mkdir(parents=True, exist_ok=True)
            if pc.exists():
                (bk / "cartuchos").mkdir(parents=True, exist_ok=True); shutil.copy2(pc, bk / "cartuchos" / nom)
            pc.write_text(txt, encoding="utf-8"); print(f"  escrito cartuchos/{nom} (sin insertar)")
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")

    for rel, marca, bloque, antes in SOFT:                              # documentacion: tolerante, nunca bloquea
        p = root / rel
        try:
            t = p.read_text(encoding="utf-8") if p.exists() else ""
            if marca in t:
                continue
            if antes and antes in t:
                t = t.replace(antes, bloque + antes, 1)
            else:
                t = t + ("" if t.endswith("\n") or not t else "\n") + bloque
            if p.exists():
                (bk / rel).parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, bk / rel)
            p.write_text(t, encoding="utf-8"); print(f"  actualizado {rel}")
        except Exception as e:
            print(f"  (aviso) no se pudo actualizar {rel}: {e!r}")
    print(f"parche-109 instalado. Copias en {bk}" if plan else "parche-109: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

